# ------------------------------------------------------------------ 3 may as "to have"
_HV = [("Meron ka na bang kalan at ibang gamit pangkusina?", "Do you already have a stove and other kitchen things?", "Wala pa rin.", "None yet also."), ("Meron ka na bang silya at mesa?", "Do you already have chairs and tables?", "Wala pa po, Kuya.", "None yet, Kuya."), ("Meron ka bang walis tingting?", "Do you have a broomstick?", "Wala akong walis tingting. Meron akong walis tambo.", "I don’t have a broomstick. I have a walis tambo."), ("Meron ka bang panlampaso?", "Do you have a mop?", "Wala din, e.", "None, too.")]
_HQ = [(q, qe) for q, qe, a, ae in _HV]
_HA = [(a, ae) for q, qe, a, ae in _HV]
_HR = [("Meron ka na bang kalan at ibang gamit pangkusina?", "Right: meron needs the linker ng on ba."), ("May kalan ka na ba at ibang gamit pangkusina?", "Right: with may/me, ba takes no linker."), ("Meron akong walis tambo.", "Right: meron needs the linker ng/g with a following personal pronoun."), ("May walis tambo ako.", "Right: with may, the pronoun follows the object and no linker is needed.")]
L3 = lesson(
    "C6 L3 · May and meron as “to have”; wala as the answer",
    "Meron ka bang panlampaso? · Wala akong walis tingting · May walis tambo ako",
    requires=[],
    cards=[
        card("May as the verb “to have”", "In Chapter 6 Lesson 1 you learned may/me/mayroon/meron as “there is/are/was/were/will be.” In this lesson they mean “to have.” Wala is the negative answer. Examples from the presentations, each with the question and the answer:", examples=passage([(q + " " + a, qe + " " + ae) for q, qe, a, ae in _HV])),
        card("Linker rules in questions", "In an interrogative sentence meron/mayroon always needs the linker ng on the enclitic ba (bang). With may/me you do not need the linker. Right: Meron ka na bang kalan at ibang gamit pangkusina? Wrong: Meron ka na ba kalan at ibang gamit pangkusina? Right: Me/May kalan ka na ba at ibang gamit pangkusina? Wrong: Me/May kalan ka na bang at ibang gamit pangkusina?", examples=passage(_HR[:2])),
        card("Linker rules in statements", "In a declarative sentence meron and mayroon always need the linker ng or g with the personal pronoun that follows immediately (akong). You do not need a linker with may. Right: Meron akong walis tambo. Wrong: Meron ako walis tambo. Right: May walis tambo ako. Wrong: May walis tambo akong. With meron/mayroon the personal pronoun subject follows the verb; with may/me it follows the direct object (walis tambo), not the verb.", examples=passage(_HR[2:])),
        card("Activities left out", "The teacher-led translation of the example sentences."),
    ],
    exercises=uniq(
        tr_q(_HQ) + rev_q(_HQ) + tr_q(_HA) + rev_q(_HA) + tr_q([("Meron akong walis tambo.", "I have a walis tambo."), ("Wala akong walis tingting.", "I don’t have a broomstick."), ("Meron akong panlampaso.", "I have a mop."), ("May walis tambo ako.", "I have a walis tambo.")])
        + [M("Which question is correct?", "Meron ka na bang kalan?", ["Meron ka na ba kalan?", "Meron ka na bang kalang?", "Meron ka na ba ng kalan?"], "meron + ng/g on ba."), M("Which question is correct?", "May kalan ka na ba?", ["May kalan ka na bang?", "May kalan na ka ba?", "May ka kalan na ba?"], "may takes no linker."), M("Which statement is correct?", "Meron akong walis tambo.", ["Meron ako walis tambo.", "May walis tambo akong.", "Meron ako ng walis tambo."], "akong."), M("Which statement is correct?", "May walis tambo ako.", ["May walis tambo akong.", "May ako walis tambo.", "May akong walis tambo."], "no linker after the object."), M("Where does the personal pronoun go with may/me?", "After the direct object", ["Right after may", "At the very beginning", "Before the noun"], "may walis tambo ako."), M("Where does the personal pronoun go with meron/mayroon?", "Right after the verb", ["After the object", "At the end of the sentence", "Before meron"], "meron akong."), M("What does Wala pa rin mean?", "None yet either.", ["None at all.", "Plenty already.", "Maybe tomorrow."], "wala pa rin."), M("What does Wala din, e mean?", "None either, you see.", ["Plenty, too.", "Maybe later.", "Not yet."], "wala din."), M("What does Wala akong walis tingting mean?", "I don’t have a broomstick.", ["I have a broomstick.", "I will buy a broomstick.", "I sold the broomstick."], "wala akong.")]
        + [F("Meron ka bang ___? (mop)", "panlampaso", ["sertipiko", "kuwadro"], "panlampaso."), F("Meron ___ walis tambo. (I have)", "akong", ["ako", "akin"], "linker."), F("Wala ___ walis tingting. (I have no)", "akong", ["ako", "ka"], "wala akong."), F("Meron ka na ___ silya at mesa? (question particle)", "bang", ["ba", "ng"], "linker."), F("Wala ___ po, Kuya. (none yet)", "pa", ["na", "din"], "wala pa.")]
    ),
)

