        + [M(f"What is the present of {inf}?", pr, dd([x[4] for x in _CJ], pr), f"{inf} → {pr}.") for r, e, inf, p, pr, f in _CJ]
        + [M(f"What is the future of {inf}?", f, dd([x[5] for x in _CJ], f), f"{inf} → {f}.") for r, e, inf, p, pr, f in _CJ]
        + [F("Bukas ___ kami sa bagong bahay. (will sweep)", "magwawalis", ["magwalis", "nagwalis"], "future."), F("Kasalukuyan silang ___ ng mga agiw. (are removing)", "nagtatanggal", ["magtanggal", "magtatanggal"], "present."), F("Kahapon ___ sina Henry ng mga gamit nila. (listed)", "naglista", ["maglista", "maglilista"], "past."), F("Kailangang ___ tayo ng banyo at sahig. (mop)", "maglampaso", ["maglalampaso", "naglampaso"], "infinitive after kailangan."), F("Kailangan nating ___ at magsabit ng kuwadro. (nail)", "magpako", ["magpapako", "nagpako"], "infinitive."), F("Umalis na ang mga bisita at ___ na rin sila. (cleaned up)", "nagligpit", ["magligpit", "magliligpit"], "past.")]
